// One-off: Wikipedia-style cross-links in the lesson text of all three guides.
// The first mention of a key term (from the flashcard glossary) in a chapter links to the section that defines it.
// Hover (mouse only) shows a short preview of the definition; click jumps there, with a "Back" bar to return.
import fs from 'node:fs';

const CODE = String.raw`
  // ---------- wiki-style cross-links (generated by tools/add-wikilinks.mjs)
  var WL=null,WLRE=null,WLMAP=null,WLTIP=null;
  function wlNorm(s){return s.toLowerCase().replace(/[\s\u00a0\u2010-\u2015-]+/g,' ').replace(/[\u2019]/g,"'").trim()}
  function wlBuild(){if(WL)return;buildIdx();const secs={};IDX.forEach(e=>{if(!e.term&&e.id)secs[e.id]=e});
   WL=[];WLMAP={};const alts=[];
   D.cards.forEach((c,ci)=>{const m=/(\d+)(?:\.(\d+))?/.exec(c.f||'');const n=m?+m[1]:0;if(!n)return;const id=m[2]&&secs['s'+n+'-'+m[2]]?'s'+n+'-'+m[2]:'';
    const raw=c.t.replace(/<[^>]+>/g,'').trim();const al=new Set();
    const add=(a,min)=>{a=a.trim();if(a.length>=(min||4))al.add(a)};
    add(raw);
    const parts=raw.split(/\s+\/\s+/);
    parts.forEach(p=>{add(p,parts.length>2&&p.split(/\s+/).length==1?7:4);const q=p.replace(/\s*\([^)]*\)\s*/g,' ').trim();if(q!==p&&(q.split(/\s+/).length>1||q.length>=9))add(q);const ac=p.match(/\(([A-Z][A-Za-z0-9]{1,7})\)/);if(ac)add(ac[1],2)});
    if(/Fitt/.test(raw))add("Fitts's Law");
    WL[ci]={ci,n,id};
    al.forEach(a=>{const k=wlNorm(a);if(!WLMAP[k]){WLMAP[k]=ci;alts.push(a)}})});
   alts.sort((a,b)=>b.length-a.length);
   const rx=a=>a.replace(/[.*+?^$()|[\]\\{}]/g,'\\$&').replace(/[\s\u00a0\u2010-\u2015-]+/g,'[\\s\\u00a0\\u2010-\\u2015-]+').replace(/['\u2019]/g,"['\\u2019]")+(/[A-Za-z]$/.test(a)?'s?':'');
   WLRE=new RegExp('(?<![\\w\\u2019\'-])('+alts.map(rx).join('|')+')(?![\\w-])','gi')}
  function wlLookup(t){const k=wlNorm(t);if(k in WLMAP)return WLMAP[k];const k2=k.replace(/s$/,'');return k2 in WLMAP?WLMAP[k2]:-1}
  function autolink(c,n){wlBuild();if(!WLRE||!WLRE.source.length)return;const done=new Set();
   const SKIP='a,button,h1,h2,h3,h4,h5,h6,.t-h1,.t-h2,.t-h3,.t-num,.gt,th,summary,pre,code,svg,.mermaid,.fcards,.fcard,.demo,.demo-slot,input,select,textarea,label,script,style,.backbar,.t-nav-footer,.endrow,.toc,.chip,.meta,.t-tag,.t-subtitle';
   const w=document.createTreeWalker(c,NodeFilter.SHOW_TEXT,{acceptNode:t=>{if(!t.nodeValue.trim())return NodeFilter.FILTER_REJECT;const p=t.parentElement;return p&&!p.closest(SKIP)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}});
   const nodes=[];while(w.nextNode())nodes.push(w.currentNode);
   nodes.forEach(t=>{const txt=t.nodeValue;WLRE.lastIndex=0;let m,last=0,frag=null;
    while((m=WLRE.exec(txt))){const ci=wlLookup(m[0]);if(ci<0||done.has(ci))continue;const it=WL[ci];
     const sec=t.parentElement.closest('.t-section[id]');const sid=sec?sec.id:'';
     if(it.n==n&&(!it.id||it.id==sid))continue; // same section: nothing to jump to
     done.add(ci);frag=frag||document.createDocumentFragment();
     if(m.index>last)frag.appendChild(document.createTextNode(txt.slice(last,m.index)));
     const a=document.createElement('a');a.className='wl';a.href='#'+(it.id||'ch'+it.n);a.dataset.ci=ci;a.dataset.n=it.n;a.dataset.id=it.id;a.dataset.src=sid;a.textContent=m[0];frag.appendChild(a);last=m.index+m[0].length}
    if(frag){if(last<txt.length)frag.appendChild(document.createTextNode(txt.slice(last)));t.parentNode.replaceChild(frag,t)}})}
  function wlHide(){if(WLTIP){WLTIP.remove();WLTIP=null}}
  function wlShow(a){wlHide();const c=D.cards[+a.dataset.ci];if(!c)return;const l=D.lessons.find(x=>x.n==+a.dataset.n);
   const d=document.createElement('div');d.className='wl-tip';d.setAttribute('role','tooltip');d.innerHTML='<b>'+c.t+'</b><div>'+c.d+'</div><small>'+(c.f||'')+' · '+(l?l.title:'')+'</small>';
   document.body.appendChild(d);const r=a.getBoundingClientRect(),h=d.offsetHeight,wd=d.offsetWidth;
   d.style.left=Math.max(8,Math.min(r.left,innerWidth-wd-8))+'px';d.style.top=(r.bottom+h+12>innerHeight&&r.top>h+12?r.top-h-8:r.bottom+6)+'px';WLTIP=d}
  __undo.push(wlHide);
  __L(document,'mouseover',e=>{if(!matchMedia('(hover:hover)').matches)return;const a=e.target.closest&&e.target.closest('a.wl');if(a)wlShow(a);else if(WLTIP&&!(e.target.closest&&e.target.closest('.wl-tip')))wlHide()});
  __L(document,'focusin',e=>{const a=e.target.closest&&e.target.closest('a.wl');if(a&&matchMedia('(hover:hover)').matches)wlShow(a)});
  __L(document,'focusout',e=>{if(e.target.closest&&e.target.closest('a.wl'))wlHide()});
  __L(document,'scroll',wlHide,true);
  __L(document,'keydown',e=>{if(e.key==='Escape')wlHide()});
  __L(document,'click',e=>{const a=e.target.closest&&e.target.closest('a.wl');if(!a)return;e.preventDefault();wlHide();const n=+a.dataset.n,l=D.lessons.find(x=>x.n==cur);
   reread(n,{tab:'theory',sel:cur,sec:a.dataset.src,label:'Back to '+(l?l.title:'the previous page')},a.dataset.id)});
`;

const CSS = `
/* ---- wiki-style cross-links ---- */
a.wl{color:#6cb2ff;text-decoration:none;cursor:pointer}
html[data-theme=light] a.wl{color:#0645ad}
a.wl:focus-visible{outline:2px solid currentColor;outline-offset:2px;border-radius:2px}
@media(hover:hover){a.wl:hover{text-decoration:underline;text-underline-offset:2px}}
.wl-tip{position:fixed;z-index:10000;max-width:min(340px,calc(100vw - 16px));padding:10px 12px;border-radius:8px;background:var(--surface2,#1c2128);color:var(--text,#e6edf3);border:1px solid var(--border,#30363d);box-shadow:0 8px 24px rgba(0,0,0,.35);font-size:12.5px;line-height:1.5;pointer-events:none}
.wl-tip b{display:block;margin-bottom:3px;font-size:13px}
.wl-tip small{display:block;margin-top:6px;color:var(--muted,#8b949e);font-size:11px}
`;

for (const id of ['algo', 'bpas', 'idp']) {
  const f = `src/courses/${id}/engine.js`;
  let s = fs.readFileSync(f, 'utf8');
  if (s.includes('wiki-style cross-links')) throw new Error(id + ' already patched');
  const hook = 'stackTables(c);mm();reveal();';
  if (!s.includes(hook)) throw new Error(id + ' hook');
  s = s.replace(hook, () => 'stackTables(c);mm();reveal();autolink(c,n);');
  const marker = '// expose bindings';
  const i = s.indexOf(marker);
  if (i < 0) throw new Error(id + ' marker');
  s = s.slice(0, i) + CODE + '\n  ' + s.slice(i);
  // goBack: return to a lesson page / section after following a wiki link
  const gb = 'function goBack(){const b=BACK;if(!b)return;';
  if (!s.includes(gb)) throw new Error(id + ' goBack');
  s = s.replace(gb, () => gb + "if(b.tab=='theory'){loadTheory(+b.sel,{focus:false});if(b.sec)setTimeout(()=>scrollToId(b.sec),450);return}");
  fs.writeFileSync(f, s);
  fs.appendFileSync(`src/courses/${id}/style.css`, CSS);
  console.log(id, 'ok');
}
// IDP only: Chapter 13 belongs with Section C
{
  const f = 'src/courses/idp/engine.js';
  let s = fs.readFileSync(f, 'utf8');
  const a = "['Section A · Introduction to evaluating designs',[1,2,3,4,5,13]]", b = "['Section C · Evaluation methods, experiments and analysis',[12,14,15,17,18,19]]";
  if (!s.includes(a) || !s.includes(b)) throw new Error('PQG');
  s = s.replace(a, "['Section A · Introduction to prototypes',[1,2,3,4,5]]").replace(b, "['Section C · Evaluation methods, experiments and analysis',[12,13,14,15,17,18,19]]");
  fs.writeFileSync(f, s);
  console.log('PQG ok');
}
